写个适配器就可以了, 比如:
```python
from datetime import timedelta

from deepagents.backends.protocol import ExecuteResponse, FileDownloadResponse, FileUploadResponse
from deepagents.backends.sandbox import BaseSandbox
from opensandbox import SandboxSync
from opensandbox.models.execd import RunCommandOpts


class OpenSandboxAdapter(BaseSandbox):

    def __init__(self, sandbox: SandboxSync):
        self.sandbox=sandbox

    def id(self) -> str:
        return self.sandbox.id

    def execute(
            self,
            command: str,
            *,
            timeout: int | None = None,
    ) -> ExecuteResponse:
        """Execute a shell command inside the sandbox."""
        result = self.sandbox.commands.run(
            command,
            opts=RunCommandOpts(
                timeout=timedelta(seconds=timeout) if timeout else None,
            )
        )
        output = result.logs.stdout[0].text if result.logs.stdout else ''
        if result.logs.stderr:
            output += f"\n<stderr>{result.logs.stderr[0].text}</stderr>"
        return ExecuteResponse(
            exit_code=result.exit_code,
            output=output,
        )

    def download_files(self, paths: list[str]) -> list[FileDownloadResponse]:
        """Download files from the sandbox."""
        responses = []
        for path in paths:
            content = self.sandbox.files.read_bytes(path)
            responses.append(FileDownloadResponse(path=path, content=content, error=None))
        return responses

    def upload_files(self, files: list[tuple[str, bytes]]) -> list[FileUploadResponse]:
        """Upload files into the sandbox."""
        responses = []
        for path, content in files:
            if not path.startswith("/"):
                responses.append(FileUploadResponse(path=path, error="invalid_path"))
                continue
            self.sandbox.files.write_file(path, content)
            responses.append(FileUploadResponse(path=path,error=None))
        return responses

    def close(self) -> None:
        """Close the sandbox."""
        if self.sandbox:
            self.sandbox.kill()

```

Question: should `cwd` expansion also consider `request.Envs`?

Right now `cwd` is expanded before `cmd.Env` is built, and `pathutil.ExpandPath` only reads the execd process env. So a request like this will fail if `WORKDIR` is not set on execd, even though the command itself would receive it via `envs`:

```json
{
  "command": "pwd",
  "cwd": "$WORKDIR",
  "envs": {
    "WORKDIR": "/tmp/ws"
  }
}
```

Is this intended, or should `cwd` be expanded using the same effective env as the command?

